// Example: trying Java 21 virtual threads in a side project

import java.util.concurrent.Executors;

public class VirtualThreadsDemo {

    public static void main(String[] args) {
        // Learning new Java features through hands-on experimentation
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {

            // Spawn 10,000 virtual threads to see performance
            for (int i = 0; i < 10_000; i++) {
                int taskId = i;
                executor.submit(() -> simulateWork(taskId));
            }

        } // executor auto-closes, waits for all tasks

        System.out.println("Completed learning experiment");
    }

    static void simulateWork(int id) {
        // Small learning projects help internalize new features
        System.out.printf("Task %d running on %s%n", 
            id, Thread.currentThread());
    }
}

