// Studying for AWS certification by building a real deployment

import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.PutObjectRequest;
import java.nio.file.Paths;

public class AwsCertificationLearning {

    public static void main(String[] args) {
        // Hands-on practice reinforces certification concepts
        var s3 = S3Client.builder().build();

        // Upload file to S3 bucket - common AWS Developer task
        var request = PutObjectRequest.builder()
            .bucket("my-learning-bucket")
            .key("uploads/test-file.txt")
            .build();

        s3.putObject(request, Paths.get("local-file.txt"));

        System.out.println("Practiced S3 upload for certification");
        // Certification prep: understand IAM permissions,
        // bucket policies, and SDK usage patterns
    }
}

