// Example: personal project that sparked backend interest

import org.springframework.web.bind.annotation.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;

@RestController
@RequestMapping("/api/cache")
public class CacheController {

    // Building a simple caching layer taught me backend fundamentals
    private final Map<String, Object> cache = new ConcurrentHashMap<>();

    @GetMapping("/{key}")
    public Object get(@PathVariable String key) {
        return cache.getOrDefault(key, "Not found");
    }

    @PostMapping("/{key}")
    public void put(@PathVariable String key, @RequestBody Object value) {
        cache.put(key, value);
        // Solving problems like this — thread safety, performance,
        // API design — is what drew me to backend development
    }
}

// Staying current by trying Java 21 features in a side project

public class PatternMatchingLearning {

    // Experimenting with new switch expressions and pattern matching
    public static String analyzeObject(Object obj) {
        return switch (obj) {
            case Integer i when i > 100 -> "Large number: " + i;
            case Integer i -> "Number: " + i;
            case String s when s.length() > 10 -> "Long string";
            case String s -> "String: " + s;
            case null -> "Null value";
            default -> "Unknown type";
        };
        // Reading release notes, then coding to internalize
    }

    public static void main(String[] args) {
        System.out.println(analyzeObject(150));
        System.out.println(analyzeObject("hello"));
    }
}
